// В HTML есть: <h1 id="title">Привет</h1>

// Находим элемент по CSS-селектору:
const h1 = document.querySelector("#title");
console.log(h1.textContent);   // "Привет" — читаем текст

// Меняем текст — страница обновится мгновенно:
h1.textContent = "Пока!";     // теперь на экране "Пока!"

// Ищем по тегу
const firstP = document.querySelector("p");

// Ищем по классу (точка = класс)
const btn = document.querySelector(".btn-primary");

// Ищем по id (решётка = id)
const header = document.querySelector("#header");

// Вложенный селектор: li внутри ul
const item = document.querySelector("ul li");

// querySelectorAll — ВСЕ подходящие элементы
const allBtns = document.querySelectorAll("button");
console.log(allBtns.length);  // сколько кнопок на странице

