theory.content:
const userInput = "<img src=x onerror=alert('XSS')>";

// ОПАСНО: innerHTML интерпретирует HTML!
// div.innerHTML = userInput;  // картинка-ловушка сработает!

// БЕЗОПАСНО: text.textContent покажет текст как есть
div.textContent = userInput;
// На экране: &lt;img src=x onerror=alert('XSS')&gt; — просто текст

// В HTML: <div id="box"><b>Жирный</b> текст</div>
const box = document.querySelector("#box");

console.log(box.textContent);  // "Жирный текст" — только буквы
console.log(box.innerHTML);    // "<b>Жирный&lt;/b&gt; текст" — с тегами

// Запись:
box.textContent = "&lt;i&gt;Курсив&lt;/i&gt;";  // покажет теги как ТЕКСТ
box.innerHTML = "<i>Курсив&lt;/i&gt;";    // создаст настоящий <i>

const box = document.querySelector(".card");

// Меняем стили (camelCase!)
box.style.color = "yellow";        // цвет текста
box.style.backgroundColor = "#000"; // фон (не background-color!)
box.style.fontSize = "24px";       // размер шрифта

// Читаем применённый inline-стиль:
console.log(box.style.color);  // "yellow"

const link = document.querySelector("a");

console.log(link.getAttribute("href"));  // читаем атрибут
link.setAttribute("target", "_blank");   // пишем атрибут

// Часто используемые — как свойства:
console.log(link.href);   // полный URL
link.textContent = "Новая ссылка";

// Создаём новый элемент
const li = document.createElement("li");
li.textContent = "Новая задача";   // заполняем содержимое
li.style.color = "yellow";         // настраиваем

// Вставляем в существующий список
document.querySelector("ul").appendChild(li);

// Альтернативы:
ul.prepend(li);          // в начало
someEl.before(li);       // перед элементом
someEl.after(li);        // после элемента

const item = document.querySelector(".old");

item.remove();  // удалили из страницы

// Объект живёт в памяти — можно вернуть:
document.querySelector("ul").appendChild(item);

const cards = document.querySelectorAll(".card");

for (const card of cards) {
  // Ищем ВНУТРИ каждой карточки:
  const title = card.querySelector("h3");
  console.log(title.textContent);
}

// parentElement — родитель, children — дети
console.log(title.parentElement);  // .card

